-- Medical dictionary spellcheck: base table + a large one-time seed of
-- clinical/device/drug vocabulary that isn't in the bundled base English
-- Hunspell dictionary (public/dictionaries/en/, see SOURCE.md). Sourced from:
--   - Progress Note dropdown values (O2 Route / Intake Route)
--   - Hand-curated pediatric high-tech home-nursing terms
--   - NIH RxTerms bulk drug list (https://lhncbc.nlm.nih.gov/MOR/RxTerms,
--     release 202608, public domain, no license required)
--   - CDC/CMS ICD-10-CM Code Descriptions FY2026
--     (https://ftp.cdc.gov/pub/health_statistics/nchs/publications/ICD10CM/2026/,
--     a US federal government work, public domain)
-- Each term was already filtered against the base dictionary's own word list
-- before being included here, so this is purely supplemental vocabulary.

CREATE TABLE "SpellcheckTerm" (
  "id"            TEXT NOT NULL,
  "term"          TEXT NOT NULL,
  "source"        TEXT NOT NULL,
  "addedByUserId" TEXT,
  "createdAt"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "SpellcheckTerm_pkey" PRIMARY KEY ("id")
);
ALTER TABLE "SpellcheckTerm" ENABLE ROW LEVEL SECURITY;

CREATE UNIQUE INDEX "SpellcheckTerm_term_key" ON "SpellcheckTerm"("term");
CREATE INDEX "SpellcheckTerm_source_idx" ON "SpellcheckTerm"("source");


